const b = $json.body ?? $json;
const pick = (...keys) => { for (const k of keys) { const v = b[k]; if (v !== undefined && v !== null && v !== '') return v; } return undefined; };

const isInstagram = b.ig_sender !== undefined;
const isSlack = b.slack_user !== undefined || b.slack_ts !== undefined;

if (isInstagram) {
  return { json: {
    external_id: String(b.ig_sender),
    channel: 'instagram',
    name: (b.name ?? null),
    message: String(b.text ?? ''),
    studio_id: 1
  } };
}

if (isSlack) {
  return { json: {
    external_id: String(b.slack_user ?? 'slack-unknown'),
    channel: 'slack',
    name: null,
    message: String(b.text ?? ''),
    studio_id: 1
  } };
}

// generic fallback (manual executions / future channels)
return { json: {
  external_id: String(pick('external_id','from','email') ?? 'unknown'),
  channel: String(pick('channel') ?? 'unknown'),
  name: (pick('name','Name') ?? null),
  message: String(pick('message','text') ?? ''),
  studio_id: Number(pick('studio_id') ?? 1)
} };

