const raw = $json.output ?? $json.text ?? '';
let data;
try {
  const m = String(raw).match(/\{[\s\S]*\}/);
  data = JSON.parse(m ? m[0] : raw);
} catch (e) {
  data = { reply: String(raw), intent: 'continue' };
}
const ZONE = 'Asia/Karachi'; // studio timezone (Pakistan Standard Time, UTC+5) — change per studio
const toZoned = (s) => {
  try {
    if (typeof s !== 'string' || !s) return s;
    const naive = s.replace(/(?:Z|[+-]\d{2}:?\d{2})$/, '');
    const dt = DateTime.fromISO(naive, { zone: ZONE });
    return dt.isValid ? dt.toISO() : naive;
  } catch (e) { return s; }
};
let booking = data.booking ?? null;
if (booking && typeof booking === 'object') {
  booking = { ...booking, start_time: toZoned(booking.start_time), end_time: toZoned(booking.end_time) };
}
return { json: {
  reply: data.reply ?? '',
  intent: data.intent ?? 'continue',
  booking: booking,
  escalate: data.escalate ?? null
} };

const n = Number($json.nudges_sent ?? 1);
const first = $json.name ? (' ' + String($json.name).trim().split(/\s+/)[0]) : '';
const msgs = [
  `Hey${first} 😊 no rush at all — I know starting something new can feel a bit daunting, especially if you're not sure it's for you yet. Our Beginner Reformer classes are small (max 8) and built for total first-timers, so you'd be in really good hands. Your 2-week unlimited intro pass is still open — want me to suggest an easy time to come try one class? No commitment, just see how it feels.`,
  `Hey${first}, just checking in one last time 💛 honestly, most of our members were on the fence before their first class and now they can't imagine their week without it. If you're even a little curious, just tell me which day suits and I'll hold a spot for you on the intro pass — nothing to lose. And if the timing isn't right, no worries at all, I'm here whenever you're ready.`
];
const idx = Math.min(Math.max(n - 1, 0), msgs.length - 1);
return { json: {
  id: $json.id,
  external_id: $json.external_id,
  channel: $json.channel,
  name: $json.name ?? null,
  last_msg: $json.last_msg ?? '',
  followup_text: msgs[idx],
  nudge_number: idx + 1,
  is_final: n >= 2
} };

const sd = $getWorkflowStaticData('global');
const items = $input.all();
// First run after activation: set cursor to newest and skip the existing backlog
if (sd.slackLastTs === undefined) {
  let mx = 0;
  for (const it of items) { const t = parseFloat(it.json.ts); if (t > mx) mx = t; }
  sd.slackLastTs = String(mx || (Date.now() / 1000));
  return [];
}
const lastTs = parseFloat(sd.slackLastTs);
let maxTs = lastTs;
const out = [];
for (const it of items) {
  const m = it.json;
  const ts = parseFloat(m.ts);
  if (!ts || ts <= lastTs) continue;
  if (m.bot_id || m.app_id || m.subtype) continue; // ignore bots / apps / system events
  if (!m.user || !m.text) continue;
  if (ts > maxTs) maxTs = ts;
  out.push({ json: { slack_user: m.user, slack_ts: m.ts, text: m.text } });
}
sd.slackLastTs = String(maxTs);
return out;

const items = $input.all();
const CAP = 8;
const classes = [];
const trials = {};
for (const it of items) {
  const j = it.json || {};
  const s = j.start && (j.start.dateTime || j.start.date);
  if (!s) continue;
  const summary = String(j.summary || '').trim();
  if (/^trial/i.test(summary)) {
    const key = new Date(s).getTime();
    trials[key] = (trials[key] || 0) + 1;
  } else {
    classes.push({ summary, start: s });
  }
}
const fmt = (iso) => DateTime.fromISO(iso, { zone: 'Asia/Karachi' }).toFormat('cccc dd LLL, h:mm a');
const lines = classes
  .sort((a, b) => new Date(a.start) - new Date(b.start))
  .map((c) => {
    const taken = trials[new Date(c.start).getTime()] || 0;
    const left = CAP - taken;
    return '- ' + c.summary + ' — ' + fmt(c.start) + ' — ' + (left > 0 ? left + ' seats left' : 'FULL');
  });
const scheduleText = lines.length ? lines.join('\n') : '(no upcoming classes on the schedule right now)';
return [{ json: { scheduleText } }];

// Verifies Meta's X-Hub-Signature-256 over the EXACT raw bytes that were signed.
// Meta may sign with either the main app secret or the Instagram-product app
// secret depending on how the subscription was created, so we accept either.
// Anything failing verification is dropped silently (returns no items).
const crypto = require('crypto');

const secrets = [$env.IG_APP_SECRET, $env.IG_APP_SECRET_INSTAGRAM].filter(Boolean);
const items = $input.all();
const out = [];

const matches = (raw, sig) => secrets.some((secret) => {
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');
  const a = Buffer.from(expected, 'utf8');
  const b = Buffer.from(String(sig), 'utf8');
  return a.length === b.length && crypto.timingSafeEqual(a, b);
});

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const headers = item.json.headers ?? {};
  const sig = headers['x-hub-signature-256'] ?? headers['X-Hub-Signature-256'];

  // Raw body arrives as a binary property (webhook option rawBody=true)
  let raw = null;
  const b64 = item.binary?.data?.data;
  if (b64) {
    raw = Buffer.from(b64, 'base64');
  } else {
    try { raw = await $helpers.getBinaryDataBuffer(i, 'data'); } catch (e) { raw = null; }
  }

  if (!secrets.length || !sig || !raw) continue;
  if (!matches(raw, sig)) continue;

  let body;
  try { body = JSON.parse(raw.toString('utf8')); } catch (e) { continue; }
  out.push({ json: { body } });
}

return out;

// Flattens Meta's batched webhook payload into one item per inbound text DM.
const out = [];

for (const item of $input.all()) {
  const body = item.json.body ?? {};
  if (body.object !== 'instagram') continue;

  for (const entry of body.entry ?? []) {
    for (const ev of entry.messaging ?? []) {
      const msg = ev.message;
      if (!msg) continue;          // delivery / read receipts
      if (msg.is_echo) continue;   // our own outbound DM echoed back
      if (!msg.text) continue;     // reactions, attachments, stickers

      out.push({ json: {
        ig_sender: ev.sender?.id,
        ig_mid: msg.mid,
        text: msg.text,
        ig_account_id: entry.id
      } });
    }
  }
}

return out;

// Meta retries aggressively; drop message IDs we've already handled.
const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.igSeenMids)) store.igSeenMids = [];

const seen = new Set(store.igSeenMids);
const out = [];

for (const item of $input.all()) {
  const mid = item.json.ig_mid;
  if (!mid) { out.push(item); continue; }
  if (seen.has(mid)) continue;
  seen.add(mid);
  store.igSeenMids.push(mid);
  out.push(item);
}

// keep the rolling window bounded
if (store.igSeenMids.length > 500) {
  store.igSeenMids = store.igSeenMids.slice(-500);
}

return out;
